import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FaTrash, FaExclamationTriangle } from 'react-icons/fa';
import './MealList.css';

const MealList = ({ meals, currentUser, onDeleteMeal, showDelete }) => {
  if (meals.length === 0) {
    return (
      <motion.div
        className="empty-state"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <div className="empty-icon">🍽️</div>
        <h3>אין ארוחות עדיין</h3>
        <p>הוסף ארוחה ראשונה כדי להתחיל!</p>
      </motion.div>
    );
  }

  return (
    <div className="meal-list">
      <AnimatePresence>
        {meals.map((meal, index) => (
          <motion.div
            key={meal.id}
            className="meal-card"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3, delay: index * 0.1 }}
            whileHover={{ y: -5 }}
            style={{ '--user-color': meal.user_color }}
          >
            <div className="meal-header">
              <div className="meal-user">
                <div 
                  className="user-indicator" 
                  style={{ backgroundColor: meal.user_color }}
                >
                  <span className="user-initial">{meal.user_name.charAt(0)}</span>
                </div>
                <div className="user-info">
                  <span className="user-name">{meal.user_name}</span>
                  <span className="meal-date">
                    {new Date(meal.created_at).toLocaleDateString('he-IL')}
                  </span>
                </div>
              </div>
              {showDelete && meal.user_id === currentUser.id && (
                <button
                  className="delete-button"
                  onClick={() => onDeleteMeal(meal.id)}
                  title="מחק ארוחה"
                >
                  <FaTrash />
                </button>
              )}
            </div>

            <div className="meal-content">
              <h3 className="meal-name">{meal.name}</h3>
              {meal.description && (
                <p className="meal-description">{meal.description}</p>
              )}
            </div>

            {meal.user_id !== currentUser.id && (
              <div className="duplicate-warning">
                <FaExclamationTriangle />
                <span>מישהו אחר כבר לקח על עצמו את זה</span>
              </div>
            )}
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
};

export default MealList;
